chrome.runtime.onInstalled.addListener(()=>{console.log("Password Vault installed")});chrome.alarms.create("autoLock",{periodInMinutes:5});chrome.alarms.onAlarm.addListener(t=>{t.name==="autoLock"&&chrome.storage.local.set({locked:!0})});chrome.runtime.onMessage.addListener((t,e,r)=>{if(t.action==="getAutofillData")return a(t.url,r),!0;if(t.action==="saveDetectedCredentials")return c(t.credentials,r),!0});async function a(t,e){try{if(!(await chrome.storage.local.get("vault_data")).vault_data){e({success:!1,error:"Vault locked"});return}e({success:!0})}catch(r){e({success:!1,error:String(r)})}}async function c(t,e){try{const r=await chrome.storage.local.get("password_vault");e({success:!0})}catch(r){e({success:!1,error:String(r)})}}
